class Solution {
public:
    int maxNumberOfBalloons(string text) {
        int cnt[26] = {0};
        for (char c : text) cnt[c - 'a']++;
        int ans = cnt['b' - 'a'];
        if (cnt['a' - 'a'] < ans) ans = cnt['a' - 'a'];
        if (cnt['l' - 'a'] / 2 < ans) ans = cnt['l' - 'a'] / 2;
        if (cnt['o' - 'a'] / 2 < ans) ans = cnt['o' - 'a'] / 2;
        if (cnt['n' - 'a'] < ans) ans = cnt['n' - 'a'];
        return ans;
    }
};
